<body>
<div class="container">
  <h1>Todo List</h1>

  <form class="add-form" id="addForm">
    <input type="text" id="todoInput" placeholder="What needs to be done?" autocomplete="off" required>
    <button type="submit">Add</button>
  </form>

  <ul class="todo-list" id="todoList"></ul>
  <div class="empty" id="emptyMsg" hidden>No todos here.</div>

  <div class="footer">
    <span id="counter">0 items left</span>
    <div class="filters">
      <button type="button" data-filter="all" class="active">All</button>
      <button type="button" data-filter="active">Active</button>
      <button type="button" data-filter="completed">Completed</button>
    </div>
    <button type="button" class="clear-btn" id="clearCompleted">Clear completed</button>
  </div>
</div>

<script>
  const STORAGE_KEY = "todos";
  let todos = loadTodos();
  let currentFilter = "all";

  const addForm = document.getElementById("addForm");
  const todoInput = document.getElementById("todoInput");
  const todoList = document.getElementById("todoList");
  const emptyMsg = document.getElementById("emptyMsg");
  const counter = document.getElementById("counter");
  const filterButtons = document.querySelectorAll(".filters button");
  const clearCompletedBtn = document.getElementById("clearCompleted");

  function loadTodos() {
    try {
      const data = JSON.parse(localStorage.getItem(STORAGE_KEY));
      return Array.isArray(data) ? data : [];
    } catch (e) {
      return [];
    }
  }

  function saveTodos() {
    localStorage.setItem(STORAGE_KEY, JSON.stringify(todos));
  }

  function generateId() {
    return Date.now().toString(36) + Math.random().toString(36).slice(2, 8);
  }

  function addTodo(text) {
    const trimmed = text.trim();
    if (!trimmed) return;
    todos.push({ id: generateId(), text: trimmed, completed: false });
    saveTodos();
    render();
  }

  function toggleTodo(id) {
    const todo = todos.find(t => t.id === id);
    if (!todo) return;
    todo.completed = !todo.completed;
    saveTodos();
    render();
  }

  function deleteTodo(id) {
    todos = todos.filter(t => t.id !== id);
    saveTodos();
    render();
  }

  function clearCompleted() {
    todos = todos.filter(t => !t.completed);
    saveTodos();
    render();
  }

  function getVisibleTodos() {
    if (currentFilter === "active") return todos.filter(t => !t.completed);
    if (currentFilter === "completed") return todos.filter(t => t.completed);
    return todos;
  }

  function render() {
    todoList.innerHTML = "";
    const visible = getVisibleTodos();

    visible.forEach(todo => {
      const li = document.createElement("li");
      li.className = "todo-item" + (todo.completed ? " completed" : "");

      const checkbox = document.createElement("input");
      checkbox.type = "checkbox";
      checkbox.checked = todo.completed;
      checkbox.addEventListener("change", () => toggleTodo(todo.id));

      const span = document.createElement("span");
      span.className = "todo-text";
      span.textContent = todo.text;
      span.addEventListener("dblclick", () => toggleTodo(todo.id));

      const delBtn = document.createElement("button");
      delBtn.className = "delete-btn";
      delBtn.type = "button";
      delBtn.title = "Delete";
      delBtn.setAttribute("aria-label", "Delete todo");
      delBtn.textContent = "×";
      delBtn.addEventListener("click", () => deleteTodo(todo.id));

      li.append(checkbox, span, delBtn);
      todoList.appendChild(li);
    });

    emptyMsg.hidden = visible.length !== 0;
    emptyMsg.textContent = todos.length === 0 ? "Nothing to do. Add a todo above!" : "No todos here.";

    const left = todos.filter(t => !t.completed).length;
    counter.textContent = left + (left === 1 ? " item left" : " items left");

    filterButtons.forEach(btn => {
      btn.classList.toggle("active", btn.dataset.filter === currentFilter);
    });
  }

  addForm.addEventListener("submit", e => {
    e.preventDefault();
    addTodo(todoInput.value);
    todoInput.value = "";
    todoInput.focus();
  });

  filterButtons.forEach(btn => {
    btn.addEventListener("click", () => {
      currentFilter = btn.dataset.filter;
      render();
    });
  });

  clearCompletedBtn.addEventListener("click", clearCompleted);

  render();
</script>
</body>
</html>
